namespace ghidra.framework.main.projectdata.actions;



using docking;
using docking;
using ghidra.app.util;
using ghidra.framework.main;
using ghidra.framework.main.datatree;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.framework.remote;
using ghidra.framework.store;
using ghidra.util;

/**
 * Dialog for viewing all the current checkouts for a single domain file.
 */
public class CheckoutsDialog : DialogComponentProvider, ProjectListener {

	private CheckoutsPanel panel;

	public CheckoutsDialog(PluginTool tool, User user, DomainFile domainFile,
			ItemCheckoutStatus[] checkouts) : base("View Checkouts for " + domainFile.getName(), false)
    {
		setHelpLocation(new HelpLocation(GenericHelpTopics.REPOSITORY, "View_Check_Outs"));
		panel = new CheckoutsPanel(rootPanel, tool, user, domainFile, checkouts);
		panel.getAccessibleContext().setAccessibleName("Checkouts");
		addWorkPanel(panel);
		addDismissButton();
		AppInfo.getFrontEndTool().addProjectListener(this);

		createActions();
	}

	/* @Override */
	protected void dismissCallback() {
		AppInfo.getFrontEndTool().removeProjectListener(this);
		close();
		panel.dispose();
	}

	/* @Override */
	public void projectClosed(Project project) {
		dismissCallback();
	}

	/* @Override */
	public void projectOpened(Project project) {
		// don't care
	}

	private void createActions() {
		panel.createActions(this);
	}

	/* @Override */
	public ActionContext getActionContext(MouseEvent @event) {

		int[] selectedRows = panel.getSelectedRows();
		return new CheckoutsActionContext(selectedRows);
	}
}
